head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > removeCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 제거합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Column 의 ID 를 설정하여 Body Cell 의 imageSrc 속성값을 제거할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 컬럼 col1~col4 는 모두 inputType=textImage + viewType=icon 이며, Column 의 imageSrc 는 즐겨찾기(빈별) 아이콘으로 동일하게 설정되어 있습니다.\n[전제] 모든 Cell 에 setCellImageSrc 로 Column 마다 서로 다른 이미지(col1=png / col2=jpg / col3=gif / col4=수정아이콘)를 미리 설정해 두었습니다.\n[절차] rowIndex 와 columnInfo(Column ID) 를 선택한 뒤 removeCellImageSrc 버튼을 실행하세요.\n[확인] columnInfo 를 인덱스 대신 Column ID(col1~col4) 로 지정해도 해당 Cell 의 이미지가 Column 의 즐겨찾기(빈별) 아이콘으로 되돌아가는지 그리드에서 확인하고, 리턴창의 제거 전·후 imageSrc 값을 확인하세요."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (textImage Cell 에 함께 표시될 텍스트 데이터)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울", "col2": "부산", "col3": "대구", "col4": "인천" },
        { "col1": "광주", "col2": "대전", "col3": "울산", "col4": "세종" },
        { "col1": "수원", "col2": "성남", "col3": "용인", "col4": "고양" },
        { "col1": "청주", "col2": "전주", "col3": "포항", "col4": "제주" }
    ]);

    // target 생성
    //  Column 단위 imageSrc 는 ico_fav.svg(빈 별) 로 동일 설정 -> Cell 단위 값 제거 시 Column 값으로 되돌아가는 것이 눈에 띄도록 함
    //  Body column 의 id 는 반드시 바인딩 DataList 의 컬럼 id(col1~col4) 와 일치해야 데이터가 렌더링됨
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:640px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" inputType="text" id="hcol1" value="col1 (textImage)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol2" value="col2 (textImage)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol3" value="col3 (textImage)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (textImage)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 제거 대상이 되는 Cell 단위 imageSrc 를 setCellImageSrc 로 미리 설정
    //  Column 마다 다른 이미지를 설정하여 Column ID 가 올바른 Column 으로 해석되는지 식별 가능하도록 구성
    let cellImageArr = ["/img/png.png", "/img/jpg.jpg", "/img/gif.gif", "/cm/images/base/ico_grid_update.svg"];
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            scwin.target1.setCellImageSrc(i, j, cellImageArr[j]);
        }
    }
}



// removeCellImageSrc 실행 : columnInfo 를 Column ID(문자열)로 지정하여 Body Cell 의 imageSrc 를 제거하고,
//                           getCellImageSrc 로 제거 전/후 값을 조회하여 리턴창에 출력
scwin.btn_removeCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // _2 : columnInfo 를 Column ID(문자열)로 그대로 전달 (Number 변환하지 않음)
    let columnInfo = par_columnInfo.getValue();

    // 제거 전 Cell 단위 imageSrc
    let before = scwin.target1.getCellImageSrc(rowIndex, columnInfo);

    // 메소드 실행 (Column ID 로 지정)
    let ret = scwin.target1.removeCellImageSrc(rowIndex, columnInfo);

    // 제거 후 Cell 단위 imageSrc
    let after = scwin.target1.getCellImageSrc(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "removeCellImageSrc(" + rowIndex + ", '" + columnInfo + "') 반환값 : " + ret
        + " | 제거 전 imageSrc : " + before + " -> 제거 후 imageSrc : " + after);
}
